const e={id:"getting-things-done",title:"Getting Things Done",author:"David Allen",courseIds:["procrastination","adhd"],sources:[{id:"gtd-identification",title:"Getting Things Done developer description",url:"https://gettingthingsdone.com/what-is-gtd/",citation:"David Allen Company. What is GTD? Official methodology description, accessed 2026-10-08.",kind:"book-identification",population:"Author/developer description, no empirical sample.",finding:"Identifies the book and themes only.",limitation:"Promotional practitioner material; not evidence for efficacy.",checkedOn:"2026-10-08"},{id:"if-then-plans",title:"Implementation intentions and goal achievement",url:"https://www.researchgate.net/profile/Peter-Gollwitzer-2/publication/37367696_Implementation_Intentions_and_Goal_Achievement_A_Meta-Analysis_of_Effects_and_Processes/links/59d91a24a6fdcc2aad0d8c1f/Implementation-Intentions-and-Goal-Achievement-A-Meta-Analysis-of-Effects-and-Processes.pdf",citation:"Gollwitzer, P. M., & Sheeran, P. (2006). Implementation intentions and goal achievement: A meta-analysis of effects and processes. Advances in Experimental Social Psychology, 38, 69–119. DOI: 10.1016/S0065-2601(06)38002-1.",kind:"meta-analysis",population:"94 tests, 8,461 participants; diverse laboratory and field goals, predominantly student samples.",finding:"Specific cue-response plans improved goal attainment on average, d = 0.65, 95% CI 0.60–0.70.",limitation:"Older synthesis includes 83 experimental and 11 correlational tests; not proof of GTD, time blocking, an ODA action, or a two-minute dose.",checkedOn:"2026-10-08",dossier:"turning-day.md T03; focus.md F04; procrastination.md P03; VERIFY.md design correction"},{id:"unfinished-goal-plans",title:"Plan making and unfinished goals",url:"https://users.wfu.edu/masicaej/MasicampoBaumeister2011JPSP.pdf",citation:"Masicampo, E. J., & Baumeister, R. F. (2011). Consider it done! Plan making can eliminate the cognitive effects of unfulfilled goals. Journal of Personality and Social Psychology, 101(4), 667–683. DOI: 10.1037/a0024192.",kind:"trial",population:"Several controlled experiments, predominantly university participants; laboratory reading, word-accessibility and anagram outcomes.",finding:"Making specific plans reduced interference associated with unfinished goals in the tested tasks.",limitation:"No validation of the full GTD system, permanent mental quiet, or equivalent benefit from a bare task list; independent direct replication not verified.",checkedOn:"2026-10-08"},{id:"progress-monitoring",title:"Does monitoring goal progress promote goal attainment?",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",citation:"Harkin, B., Webb, T. L., Chang, B. P. I., Prestwich, A., Conner, M., Kellar, I., Benn, Y., & Sheeran, P. (2016). Does monitoring goal progress promote goal attainment? A meta-analysis of the experimental evidence. Psychological Bulletin, 142(2), 198–229. DOI: 10.1037/bul0000025.",kind:"meta-analysis",population:"138 randomized studies, 19,951 participants with varied goals.",finding:"Goal attainment improved on average, d = 0.40, 95% CI 0.32–0.48 in opened abstract.",limitation:"Protocols varied; recording/reporting moderators do not validate a particular tracker, streak rule or review schedule.",checkedOn:"2026-10-08",dossier:"turning-day.md T05; focus.md F03; procrastination.md P13"},{id:"adult-adhd-cbt",title:"Cognitive-behavioural therapy for adult ADHD",url:"https://www.cochrane.org/evidence/CD010840_cognitive-behavioural-therapy-attention-deficit-hyperactivity-disorder-adhd-adults",citation:"Lopez, P. L., Torrente, F. M., Ciapponi, A., Lischinsky, A. G., Cetkovich-Bakmas, M., Rojas, J. I., Romano, M., & Manes, F. F. (2018). Cognitive-behavioural interventions for attention deficit hyperactivity disorder in adults. Cochrane Database of Systematic Reviews, 3, CD010840. DOI: 10.1002/14651858.CD010840.pub2.",kind:"systematic-review",population:"14 randomized trials, 700 adults aged 18–65 with ADHD; search through June 2017.",finding:"Structured CBT packages showed qualified symptom benefits; results depend on comparator, certainty very low to moderate.",limitation:"Does not isolate task lists or timers, establish GTD as treatment, or justify medication changes; little long-term evidence.",checkedOn:"2026-10-08",dossier:"adhd.md S01; focus.md F11"},{id:"adhd-skills-protocol",title:"Description and demonstration of CBT for adult ADHD",url:"https://ica.org.il/wp-content/uploads/2024/06/Description-and-Demonstration-of-CBT-for-ADHD-in-Adults-1.pdf",citation:"Sprich, S. E., Knouse, L. E., Cooper-Vince, C., Burbridge, J., & Safren, S. A. Description and demonstration of CBT for ADHD in adults. Cognitive and Behavioral Practice, 17(1), 9–15. DOI: 10.1016/j.cbpra.2009.09.002. Journal issue identified as 2010; opened manuscript header labels February 2012.",kind:"review",population:"Developer protocol demonstration; role-play clients are actors, no new efficacy trial.",finding:"Task lists, calendars, step breakdown and distractibility delay occur within a clinician-delivered package.",limitation:"No isolated component efficacy; manuscript/journal date discrepancy preserved, no claim of independent validation of GTD.",checkedOn:"2026-10-08",dossier:"adhd.md S09; VERIFY.md date discrepancy"}],locales:{en:{hook:"Your task list is full, but nothing tells you what to do next. Make one item executable.",intro:"Allen’s central practical concern is how to handle commitments without having to reconstruct them whenever you begin work. ODA examines the clarity of the next action, the plan for an unfinished obligation, the accuracy of a review and the limits of a personal organizing system. These themes need separate verdicts: evidence for planning does not validate every feature of a complete productivity method. Start with one item that keeps returning to mind. You can use paper or an existing free notes tool, and you do not need to reorganize your life before making a useful decision.",ideas:[{id:"executable-next-step",title:"Turn a commitment into an observable next action",idea:"Allen asks readers to decide what doing something would mean before they meet the moment when it must be done. Replace a broad project label with one action that has a visible start and a sensible stopping point, then check whether it needs information, another person or a resource you do not yet have. For an ODA adaptation, a delayed application can become opening the form and identifying the first missing detail, rather than a vague promise to deal with it. A clear action may still be difficult, but at least the plan tells you which difficulty you are facing.",research:"Specific cue-response plans have meta-analytic support: Gollwitzer and Sheeran reported improved goal attainment across 94 varied tests. The evidence concerns linking a recognizable situation to a selected behavior, not proving Allen’s entire system or showing that wording alone removes avoidance. A concrete next action gains a stronger research connection when you also specify a realistic opportunity to attempt it. Keep the verdict bounded to planning for execution; a list that only names projects, or a plan that depends on unavailable help, has not thereby acquired the benefits measured in the reviewed studies.",verdict:"supported",sourceIds:["if-then-plans"]},{id:"unfinished-obligation",title:"Pair the reminder with a credible plan",idea:"The book proposes placing commitments in an external system so they can be revisited without repeatedly rebuilding the same decision in your head. The useful distinction is between recording a worry and deciding how you will handle the part you can act on, because a long collection of unresolved reminders can still demand attention. Write the next feasible action and when you will review it; if you are waiting for someone, record what you are waiting for instead of inventing work. A reminder should preserve information, while the plan should make the next choice easier to locate.",research:"Masicampo and Baumeister found in controlled experiments that specific plans reduced some interference from unfinished goals on unrelated laboratory tasks. Participants were largely university students, and the outcomes included reading, word accessibility and anagram performance. This is promising support for the distinction between an unplanned goal and a planned one, not proof that capturing everything into a list produces lasting mental calm. The paper does not test the full organizing system or the two-minute action below, and independent direct confirmation of this specific procedure remains uncertain. Try a credible plan for one recurring obligation and assess the practical result yourself.",verdict:"mixed",sourceIds:["unfinished-goal-plans"]},{id:"current-record",title:"Review whether the list still describes reality",idea:"Allen’s approach depends on revisiting commitments, since an old plan can stop matching the work, time and responsibilities you actually have. Use a review to remove completed items, identify a blocked action and decide which remaining item deserves a real opportunity, rather than admiring how comprehensive the list looks. If the list has grown beyond your available capacity, reduce or renegotiate commitments instead of simply arranging them more neatly. A review should help you make a decision about work; it becomes another avoidance task if it repeatedly replaces the action you already know how to begin.",research:"Harkin and colleagues found an average goal-attainment benefit from progress-monitoring interventions in 138 randomized studies. That supports checking a plan against observed progress, but the studies used varied formats and do not identify one universally optimal weekly ritual. Their recording and reporting moderators do not mean you must share private commitments or that tidying a list counts as completing them. The supported principle is to examine actual progress and respond to what it shows. Compare intended action, attempted action and result, then change the plan where they diverge rather than treating the mere existence of a review as evidence of effectiveness.",verdict:"supported",sourceIds:["progress-monitoring"]},{id:"support-boundary",title:"Build a system you can actually use",idea:"Allen wants commitments kept in an external system current and accessible enough to support practical choices about work. Start with a place you will actually consult, keep the administration modest, and adjust the structure when maintaining it takes more effort than useful action. The test is whether you can find a concrete decision or recognize a commitment to renegotiate, not whether the archive looks perfect. If persistent difficulties affect several areas of life, consider qualified support while trying everyday aids; completing this method is not a prerequisite for assessment or accommodations.",research:"A Cochrane review of 14 randomized adult-ADHD trials found qualified benefits from structured cognitive-behavioral packages, with certainty ranging from very low to moderate and results depending on the comparator. Task lists and calendars appear in a published clinical protocol, but those ingredients were not independently validated as treatment in that description. Neither source establishes Getting Things Done as ADHD care or proves that a reminder solves a clinical difficulty. The verdict is mixed for extending the organizing advice to persistent attention problems: it may be an everyday aid, while ODA is not treatment and medication decisions belong with your clinician.",verdict:"mixed",sourceIds:["adult-adhd-cbt","adhd-skills-protocol"]}],action:{title:"Clarify one stuck item in two minutes",steps:["Choose one unfinished commitment and write the next visible action that could start today.","Write when or at which familiar cue you could attempt it, including any missing information.","Put that single plan in your usual notes place and leave room to record the later attempt."],decision:"Today I will write one next action, a feasible opportunity, and any missing information for a stuck commitment."},takeaway:"Keep the concrete action and the review that checks reality. Treat the larger promise of a permanently clear mind with caution: planning experiments do not establish that a complete productivity system will remove stress. Today’s two-minute clarification is an ODA adaptation, not a tested treatment dose. If the barrier is excessive workload or persistent impairment, the next useful action may be asking for support. A system earns its place by helping you act or renegotiate, not by becoming another standard you must live up to."},tr:{hook:"İş listen dolu, ama sırada ne yapacağını söylemiyor. Bir maddeyi gerçekten uygulanabilir hale getir.",intro:"Allen’ın temel pratik derdi, bir işe başlarken sorumluluklarını her seferinde yeniden kurmak zorunda kalmaman. ODA, sıradaki eylemin açıklığını, bitmemiş bir iş için planı, değerlendirmenin doğruluğunu ve kişisel düzenleme sisteminin sınırlarını inceliyor. Bu fikirler ayrı sonuçlar gerektiriyor; planlamaya destek veren bulgular kapsamlı bir verimlilik yönteminin her özelliğini doğrulamıyor. Aklına tekrar tekrar gelen tek bir maddeyle başla. Kâğıt ya da zaten kullandığın ücretsiz bir not aracı yeterli olabilir. İşe yarar bir karar vermeden önce bütün hayatını yeniden düzenlemen gerekmiyor; bugün seçtiğin maddenin hangi kısmında gerçekten hareket edebileceğini açıklığa kavuşturabilirsin.",ideas:[{id:"executable-next-step",title:"Sorumluluğu gözlenebilir bir sonraki eyleme çevir",idea:"Allen, yapılması gereken an gelmeden önce bir şeyi yapmanın gerçekte ne anlama geleceğini belirlemeni istiyor. Geniş bir proje adını, görünür başlangıcı ve makul durma noktası olan tek bir eylemle değiştir; bunun bilgi, başka biri veya henüz sahip olmadığın bir kaynak gerektirip gerektirmediğini de kontrol et. ODA uyarlaması olarak, geciken bir başvuru belirsiz bir halletme sözünden çıkıp formu açmak ve ilk eksik bilgiyi belirlemek olabilir. Açık bir eylem yine de zor gelebilir, ama en azından hangi güçlükle karşılaştığını gösterir; eksik bir bilgiyle işe başlamak istememek, ne yapacağını hiç belirlememekten farklıdır.",research:"Belirli bir durumu bir karşılığa bağlayan planlara meta-analitik destek var: Gollwitzer ve Sheeran, farklı koşullardaki 94 sınamada hedefe ulaşmada iyileşme bildirdi. Bulgular, fark edilebilir bir durumu seçilen davranışla ilişkilendirmeye yönelik; Allen’ın bütün sistemini kanıtlamıyor veya yalnızca doğru kelimeleri yazmanın kaçınmayı kaldırdığını göstermiyor. Somut eyleme, deneyeceğin gerçekçi fırsatı da eklediğinde araştırmayla bağlantı güçleniyor. Desteklenen alanı uygulama planıyla sınırlı tut. Yalnızca projelerin adını sıralayan bir liste veya bulunmayan desteğe bağlı bir plan, bu yüzden araştırmalardaki faydayı kazanmış sayılmaz. Yazdığın fırsat ortaya çıkmadığında bunu kaydet ve yeni fırsatı koşullara göre seç, gerçekleşmemiş planı başarı olarak sayma.",verdict:"supported",sourceIds:["if-then-plans"]},{id:"unfinished-obligation",title:"Hatırlatıcıya inandırıcı bir plan ekle",idea:"Kitap, sorumluluklarını dışarıdaki bir sistemde tutmanı öneriyor; böylece aynı kararı zihninde tekrar tekrar kurmadan geri dönebilirsin. Yararlı ayrım, bir endişeyi yazmak ile üzerinde hareket edebileceğin kısmı nasıl ele alacağını belirlemek arasında; uzun bir çözümsüz hatırlatıcı listesi yine dikkat isteyebilir. Bir sonraki uygun eylemi ve ne zaman gözden geçireceğini yaz, birinden cevap bekliyorsan kendine iş uydurmak yerine neyi beklediğini belirt. Hatırlatıcı bilgiyi saklasın, plan da sonraki seçimi bulmanı kolaylaştırsın; bütün sorumlulukların aynı anda çözülecekmiş gibi bir liste hazırlamak zorunda değilsin.",research:"Masicampo ve Baumeister, kontrollü deneylerde belirli planların bitmemiş hedeflerden kaynaklanan bazı zihinsel engellemeleri ilgisiz laboratuvar görevlerinde azalttığını buldu. Katılımcılar çoğunlukla üniversite öğrencisiydi; sonuçlar okuma, kelimelere erişim ve anagram görevlerini içeriyordu. Bu, plansız hedef ile planlanmış hedef arasındaki ayrıma umut veren destek, her şeyi listeye yazmanın kalıcı zihinsel huzur yarattığının kanıtı değil. Çalışma, kapsamlı düzenleme sistemini veya aşağıdaki iki dakikalık eylemi sınamıyor; bu özel uygulamanın bağımsız doğrudan doğrulanması da belirsiz. Tek bir tekrar eden sorumluluk için inandırıcı plan dene ve pratik sonucunu gözle. Daha sakin hissetsen bile bunun sürekli olacağını veya bütün işleri tamamladığını varsayma; plan ile yapılan iş yine ayrı şeyler.",verdict:"mixed",sourceIds:["unfinished-goal-plans"]},{id:"current-record",title:"Listenin hâlâ gerçeği anlatıp anlatmadığına bak",idea:"Allen’ın yaklaşımı sorumluluklara tekrar bakmaya dayanıyor, çünkü eski bir plan mevcut işine, zamanına ve görevlerine uymayı bırakabilir. Değerlendirmeyi, listenin ne kadar kapsamlı olduğuna hayran kalmak için değil; tamamlananı çıkarmak, takılan eylemi bulmak ve kalan maddelerden hangisine gerçek fırsat vereceğini seçmek için kullan. Liste kapasitenin ötesine büyüdüyse yalnızca daha düzgün sıralamak yerine sorumluluklarını azalt veya ilgili kişilerle yeniden görüş. Değerlendirme iş hakkında karar vermene yardım etsin; nasıl başlayacağını zaten bildiğin eylemin yerini sürekli aldığında kendisi de bir erteleme işi olabilir, bu yüzden kayıt düzenlemek ile ilerleme üretmek arasındaki ayrımı koru.",research:"Harkin ve çalışma arkadaşları, 138 rastgele atamalı çalışmada ilerleme izleme müdahalelerinin hedefe ulaşmaya ortalama katkısını buldu. Bu, planı gözlenen ilerlemeyle karşılaştırmayı destekliyor; çalışmalarda farklı biçimler kullanıldı ve hepsi için en iyi haftalık ritüel belirlenmedi. Kayıt ve paylaşma hakkındaki karşılaştırmalar, özel sorumluluklarını başkalarıyla paylaşman gerektiği veya listeyi temizlemenin onları tamamlamak sayıldığı anlamına gelmiyor. Desteklenen ilke, gerçek ilerlemeyi inceleyip gösterdiğine cevap vermek. Planlanan eylemi, denenen eylemi ve sonucu karşılaştır; aradaki farkın olduğu yerde planı değiştir. Sırf değerlendirme yaptığın için yöntemin etkili olduğunu varsayma, onu sonraki seçime bağlayan somut bilgiye bak ve paylaşmayı güvenli, isteğe bağlı tut.",verdict:"supported",sourceIds:["progress-monitoring"]},{id:"support-boundary",title:"Gerçekten kullanabileceğin bir sistem kur",idea:"Allen, sorumlulukların iş hakkında karar verirken başvurabileceğin kadar güncel ve ulaşılabilir bir dış sistemde tutulmasını istiyor. Gerçekten bakacağın tek bir yerle başla, idari işi sınırlı tut ve bakımı işe yarar eylemden fazla çaba istediğinde yapıyı değiştir. Sistemin değeri kusursuz bir arşiv görünümünde değil, somut kararı bulmana veya yeniden görüşmen gereken sorumluluğu fark etmene yardım etmesinde olsun. Kalıcı güçlükler hayatının farklı alanlarını etkiliyorsa gündelik destekleri denerken yetkin bir uzmanı da düşün; değerlendirme veya uygun düzenlemeler için bu yöntemi tamamlaman, kursta başarısız olman veya disiplinini kanıtlaman önkoşul değil.",research:"Cochrane’ın yetişkin DEHB konusunda 14 rastgele atamalı çalışmayı inceleyen derlemesi, yapılandırılmış bilişsel davranışçı paketler için koşullu faydalar buldu. Kanıtın kesinliği çok düşükten ortaya değişiyordu ve sonuçlar karşılaştırma grubuna bağlıydı. Yayımlanmış bir klinik uygulama açıklamasında görev listeleri ve takvimler var, fakat o açıklamada bu bileşenler ayrı ayrı tedavi olarak doğrulanmadı. Kaynakların hiçbiri Getting Things Done yöntemini DEHB bakımı olarak kanıtlamıyor veya bir hatırlatıcının klinik güçlüğü çözdüğünü göstermiyor. Tavsiyeyi kalıcı dikkat sorunlarına genişletmek için sonuç karışık: günlük yardımcı olabilir; ODA tedavi değil ve ilaç kararları klinisyeninle birlikte alınmalı. Günlük planını denemek, değerlendirmeyi ertelemene neden olmak zorunda değil.",verdict:"mixed",sourceIds:["adult-adhd-cbt","adhd-skills-protocol"]}],action:{title:"İki dakikada takılan bir maddeyi netleştir",steps:["Bitmemiş tek bir sorumluluk seç ve bugün başlayabileceğin görünür sıradaki eylemi yaz.","Hangi zamanda veya tanıdık işarette deneyeceğini ve hangi bilginin eksik olduğunu belirt.","Bu tek planı normal not yerine koy ve daha sonra denemeyi kaydedeceğin yeri ayır."],decision:"Bugün takılan bir sorumluluğun sonraki eylemini, deneme fırsatını ve eksik bilgisini yazacağım."},takeaway:"Somut eylemi ve gerçekle karşılaştıran değerlendirmeyi koru. Sürekli berrak bir zihin gibi büyük vaatlere temkinli yaklaş; planlama deneyleri bütün bir verimlilik sisteminin stresi kaldıracağını göstermiyor. İki dakikalık netleştirme, ODA’nın uyarlaması; sınanmış tedavi süresi değil. Engel aşırı iş yükü veya kalıcı işlev kaybıysa, sonraki yararlı adım destek istemek olabilir. Sistem, eylemine ya da sorumluluklarını yeniden görüşmene yardım ettiği kadar yerini hak eder. Ona uymayı başarman gereken yeni bir standart gibi davranmadan, hangi kararını kolaylaştırdığını gözle ve yetersiz kaldığı noktayı açıkça not et."},es:{hook:"Tu lista está llena, pero no sabes por dónde empezar. Convierte un pendiente en una acción concreta.",intro:"Allen se centra en cómo gestionar compromisos sin tener que reconstruirlos mentalmente cada vez que empiezas a trabajar. ODA examina la claridad de la siguiente acción, el plan para una obligación pendiente, la exactitud de la revisión y los límites del sistema personal. Cada tema necesita un veredicto propio: las pruebas a favor de planificar no validan todas las características de un método completo de productividad. Empieza con un asunto que vuelva a tu cabeza. Puedes usar papel o una herramienta gratuita que ya tengas; tomar una decisión útil no exige reorganizar primero toda tu vida ni completar un inventario perfecto.",ideas:[{id:"executable-next-step",title:"Convierte el compromiso en una acción observable",idea:"Allen propone decidir qué significa hacer algo antes de llegar al momento de ejecutarlo. Sustituye el nombre amplio de un proyecto por una acción con inicio visible y final razonable, y comprueba si requiere información, otra persona o un recurso que todavía no tienes. Como adaptación de ODA, una solicitud aplazada puede convertirse en abrir el formulario e identificar el primer dato que falta, en lugar de prometer vagamente que te ocuparás de ella. Una acción clara puede seguir siendo difícil, pero al menos permite distinguir qué dificultad tienes delante y qué necesitarías para abordarla.",research:"Los planes específicos que conectan una señal con una respuesta cuentan con apoyo metaanalítico: Gollwitzer y Sheeran encontraron mejores resultados de logro de objetivos en 94 pruebas diversas. La evidencia trata de vincular una situación reconocible con una conducta elegida, no de probar el sistema entero de Allen ni demostrar que redactar bien elimina la evitación. Una acción concreta se acerca más al procedimiento investigado cuando también defines una oportunidad realista para intentarla. Limita el veredicto favorable a planificar la ejecución. Una lista de proyectos o un plan que depende de ayuda inaccesible no recibe automáticamente los beneficios observados en esas investigaciones.",verdict:"supported",sourceIds:["if-then-plans"]},{id:"unfinished-obligation",title:"Añade un plan creíble al recordatorio",idea:"El libro propone guardar los compromisos en un sistema externo para volver a ellos sin rehacer una y otra vez la misma decisión en tu cabeza. Conviene distinguir entre registrar una preocupación y decidir cómo abordar su parte accionable, porque una colección de asuntos sin resolver puede seguir reclamando atención. Escribe el siguiente paso viable y cuándo lo revisarás; si esperas una respuesta, indica qué falta en vez de inventar actividad. El recordatorio conserva información y el plan facilita encontrar la próxima elección, sin fingir que todo podrá resolverse de inmediato.",research:"Masicampo y Baumeister observaron en experimentos controlados que los planes específicos reducían algunas interferencias de objetivos pendientes en tareas de laboratorio no relacionadas. Participaron sobre todo estudiantes universitarios, y se midieron lectura, accesibilidad de palabras y resolución de anagramas. Es un apoyo prometedor para distinguir un objetivo sin plan de otro planificado, no una prueba de calma mental duradera al capturarlo todo en una lista. El artículo no comprueba el sistema completo ni la acción de dos minutos propuesta abajo; la confirmación directa independiente de este procedimiento sigue siendo incierta. Prueba un plan creíble para una obligación recurrente y evalúa su resultado práctico sin dar por terminada la obligación.",verdict:"mixed",sourceIds:["unfinished-goal-plans"]},{id:"current-record",title:"Comprueba si la lista sigue describiendo la realidad",idea:"El enfoque de Allen depende de revisar compromisos, porque un plan antiguo puede dejar de encajar con el trabajo, el tiempo y las responsabilidades disponibles. Utiliza la revisión para retirar lo terminado, detectar una acción bloqueada y decidir qué asunto merece una oportunidad real, no para admirar lo exhaustiva que parece la lista. Si supera tu capacidad, reduce o renegocia compromisos en vez de ordenarlos con más elegancia. Revisar debe ayudarte a decidir sobre el trabajo; se convierte en otra forma de aplazarlo si sustituye repetidamente la acción que ya sabes cómo empezar.",research:"Harkin y sus colegas encontraron un beneficio medio de las intervenciones de seguimiento en 138 estudios aleatorizados. Esto apoya comparar el plan con el progreso observado, pero los formatos variaban y no identifican un ritual semanal óptimo para todo el mundo. Los resultados sobre registro y comunicación no obligan a compartir compromisos privados ni significan que ordenar una lista equivalga a cumplirlos. El principio respaldado es examinar el avance real y responder a lo que muestra. Compara intención, intento y resultado; modifica el plan donde diverjan, en vez de tomar la existencia de una revisión como prueba de eficacia del sistema.",verdict:"supported",sourceIds:["progress-monitoring"]},{id:"support-boundary",title:"Construye un sistema que puedas usar de verdad",idea:"Allen propone guardar los compromisos en un sistema externo suficientemente actualizado y accesible para orientar las decisiones sobre el trabajo. Empieza por un lugar que realmente consultarás, limita la administración y modifica la estructura cuando mantenerla demande más esfuerzo que actuar. Su valor consiste en encontrar una decisión concreta o reconocer un compromiso que conviene renegociar, sin necesitar un archivo perfecto. Si las dificultades persistentes afectan varias áreas de la vida, considera apoyo cualificado mientras pruebas ayudas cotidianas; completar este método no es un requisito para pedir evaluación ni conversar sobre adaptaciones.",research:"Una revisión Cochrane de 14 ensayos aleatorizados en personas adultas con TDAH encontró beneficios condicionados de programas estructurados de terapia cognitivo-conductual. La certeza de la evidencia iba de muy baja a moderada, y los resultados dependían del grupo de comparación. Las listas y los calendarios aparecen en un protocolo clínico publicado, pero sus componentes no se validaron allí por separado como tratamiento. Ninguna fuente establece que Getting Things Done sea atención para el TDAH ni que un recordatorio resuelva una dificultad clínica. El veredicto es mixto para extender estos consejos a problemas persistentes de atención: pueden servir de apoyo diario, mientras ODA no es tratamiento y las decisiones sobre medicación corresponden a tu profesional sanitario.",verdict:"mixed",sourceIds:["adult-adhd-cbt","adhd-skills-protocol"]}],action:{title:"Aclara un pendiente en dos minutos",steps:["Elige un compromiso sin terminar y escribe la siguiente acción visible que podrías empezar hoy.","Indica una hora o señal habitual para intentarla y cualquier información que falte.","Guarda ese único plan donde sueles consultar tus notas y deja espacio para registrar el intento."],decision:"Hoy escribiré la siguiente acción de un pendiente, una oportunidad para intentarla y cualquier dato que falte."},takeaway:"Conserva la acción concreta y la revisión que contrasta con la realidad. Toma con cautela la promesa de una mente permanentemente despejada: los experimentos de planificación no establecen que todo un sistema elimine el estrés. Esta aclaración de dos minutos es una adaptación de ODA, no una dosis de tratamiento probada. Si la barrera es una carga excesiva o una dificultad persistente, pedir apoyo puede ser el siguiente paso útil. Un sistema merece su lugar cuando ayuda a actuar o renegociar, sin convertirse en otro estándar al que tienes que estar a la altura."},fr:{hook:"Ta liste est pleine, mais elle ne dit pas quoi faire maintenant. Rends un élément exécutable.",intro:"Allen s’intéresse à la gestion des engagements sans devoir les reconstruire mentalement chaque fois que tu commences. ODA regarde la clarté de l’action suivante, le plan pour une obligation inachevée, la précision du bilan et les limites d’un système personnel. Chaque thème appelle un verdict distinct: les données favorables à la planification ne valident pas tout un programme de productivité. Commence par un élément qui revient régulièrement à l’esprit. Le papier ou un outil gratuit déjà disponible peuvent suffire. Une décision utile ne t’oblige pas à réorganiser toute ta vie ni à produire une liste parfaite avant d’agir.",ideas:[{id:"executable-next-step",title:"Transforme l’engagement en prochaine action observable",idea:"Allen invite à décider ce que faire une chose veut dire avant de rencontrer le moment de l’exécution. Remplace l’intitulé général d’un projet par une action avec un début visible et un arrêt raisonnable, puis vérifie si elle exige une information, une personne ou une ressource encore absente. Comme adaptation ODA, une candidature repoussée peut devenir ouvrir le formulaire et repérer la première donnée manquante, plutôt qu’une vague promesse de s’en occuper. L’action peut rester difficile, mais tu vois au moins quelle difficulté est devant toi et ce qui permettrait d’y répondre.",research:"Les plans précis reliant une situation à une réponse disposent d’un soutien méta-analytique: Gollwitzer et Sheeran ont constaté une amélioration moyenne de l’atteinte des objectifs dans 94 tests variés. Ces données concernent une situation reconnaissable associée à un comportement choisi, pas le système entier d’Allen ni la disparition de l’évitement grâce à une meilleure formulation. Une action concrète se rapproche davantage du principe étudié lorsque tu définis aussi une occasion réaliste. Limite le verdict favorable à la préparation de l’exécution. Une liste de projets ou un plan dépendant d’une aide indisponible n’acquiert pas automatiquement les bénéfices des études.",verdict:"supported",sourceIds:["if-then-plans"]},{id:"unfinished-obligation",title:"Ajoute au rappel un plan crédible",idea:"Le livre propose de placer les engagements dans un système externe afin de les retrouver sans refaire sans cesse la même décision dans ta tête. Distingue le fait de noter une préoccupation et celui de décider comment traiter sa partie réalisable, car une collection d’éléments non résolus peut toujours demander de l’attention. Écris la prochaine action possible et le moment de révision; si tu attends quelqu’un, indique ce que tu attends au lieu d’inventer de l’activité. Le rappel conserve l’information, tandis que le plan rend le prochain choix plus facile à retrouver, sans supposer que tout est immédiatement résoluble.",research:"Dans des expériences contrôlées, Masicampo et Baumeister ont trouvé que des plans précis réduisaient certaines interférences de buts inachevés dans des tâches de laboratoire sans rapport. Les participants étaient surtout des étudiants, avec des mesures de lecture, d’accessibilité des mots et d’anagrammes. C’est un soutien prometteur à la distinction entre un objectif planifié et non planifié, pas la preuve d’un calme durable après avoir tout inscrit sur une liste. L’article ne teste ni le système complet ni l’action de deux minutes proposée ici; la confirmation directe indépendante de cette procédure reste incertaine. Essaie un plan crédible pour une obligation récurrente et examine son résultat pratique sans compter l’obligation comme terminée.",verdict:"mixed",sourceIds:["unfinished-goal-plans"]},{id:"current-record",title:"Vérifie que la liste décrit encore ta réalité",idea:"L’approche d’Allen dépend d’un retour sur les engagements, car un ancien plan peut cesser de correspondre au travail, au temps et aux responsabilités réels. Utilise le bilan pour enlever ce qui est terminé, repérer une action bloquée et choisir une occasion réelle pour un élément restant, plutôt que d’admirer l’exhaustivité de la liste. Si elle dépasse ta capacité, réduis ou renégocie les engagements au lieu de simplement mieux les classer. Le bilan doit soutenir une décision sur le travail; il peut devenir une autre tâche d’évitement s’il remplace toujours l’action que tu sais déjà commencer.",research:"Harkin et ses collègues ont trouvé un bénéfice moyen des interventions de suivi dans 138 études randomisées. Cela soutient la comparaison entre un plan et des progrès observés, mais les formats variés ne désignent pas un rituel hebdomadaire optimal pour chacun. Les analyses sur le relevé et le partage n’imposent pas de divulguer des engagements privés ni de compter une liste rangée comme du travail accompli. Le principe soutenu est de regarder l’avancée réelle et d’y répondre. Compare intention, tentative et résultat, puis modifie le plan là où ils divergent; la simple tenue d’un bilan ne constitue pas une preuve d’efficacité.",verdict:"supported",sourceIds:["progress-monitoring"]},{id:"support-boundary",title:"Construis un système que tu peux vraiment utiliser",idea:"Allen veut conserver les engagements dans un système externe assez à jour et accessible pour soutenir les décisions sur le travail. Commence par un endroit que tu consulteras réellement, limite l’administration et modifie la structure quand son entretien coûte plus d’effort que l’action utile. Sa valeur tient à une décision concrète retrouvée ou à un engagement à renégocier, sans exiger une archive parfaite. Si des difficultés persistantes affectent plusieurs domaines de la vie, envisage un soutien qualifié pendant les essais ordinaires; terminer cette méthode n’est pas un préalable à une évaluation ou à des aménagements.",research:"Une revue Cochrane de 14 essais randomisés auprès d’adultes ayant un TDAH a trouvé des bénéfices nuancés de programmes structurés de thérapie cognitivo-comportementale. La certitude allait de très faible à modérée et les résultats dépendaient du groupe comparateur. Des listes et calendriers figurent dans un protocole clinique publié, mais leurs effets thérapeutiques n’y sont pas validés séparément. Aucune de ces sources ne fait de Getting Things Done un soin du TDAH ni ne démontre qu’un rappel résout une difficulté clinique. Le verdict est mitigé pour étendre ce conseil aux problèmes persistants: il peut soutenir le quotidien, tandis qu’ODA n’est pas un traitement et que les décisions de médicament appartiennent à ton suivi médical.",verdict:"mixed",sourceIds:["adult-adhd-cbt","adhd-skills-protocol"]}],action:{title:"Clarifie un engagement bloqué en deux minutes",steps:["Choisis un engagement inachevé et écris une prochaine action visible que tu pourrais commencer aujourd’hui.","Indique une heure ou un repère familier pour l’essayer, ainsi que l’information manquante.","Range ce seul plan dans tes notes habituelles et laisse une place pour noter la tentative."],decision:"Aujourd’hui, j’écrirai la prochaine action d’un engagement, son occasion et les informations manquantes."},takeaway:"Garde l’action concrète et le bilan qui vérifie la réalité. Reste prudent devant la promesse d’un esprit toujours dégagé: des expériences de planification ne prouvent pas qu’un système entier supprime le stress. La clarification de deux minutes est une adaptation ODA, pas une dose de traitement testée. Si le problème est une charge excessive ou une difficulté persistante, demander du soutien peut être la prochaine action utile. Un système mérite sa place quand il aide à agir ou à renégocier, sans devenir une norme supplémentaire à laquelle il faudrait absolument correspondre."},de:{hook:"Deine Aufgabenliste ist voll, aber der nächste Schritt fehlt. Mach einen Punkt wirklich ausführbar.",intro:"Allen beschäftigt sich damit, Verpflichtungen zu handhaben, ohne sie beim Arbeitsbeginn jedes Mal im Kopf neu aufbauen zu müssen. ODA prüft die Klarheit der nächsten Handlung, den Plan für einen offenen Punkt, die Genauigkeit einer Übersicht und die Grenzen eines persönlichen Systems. Diese Themen brauchen einzelne Urteile: Evidenz für Planung bestätigt nicht jede Eigenschaft einer vollständigen Produktivitätsmethode. Beginne mit einem Punkt, der immer wieder auftaucht. Papier oder ein vorhandenes kostenloses Notizwerkzeug können reichen. Eine hilfreiche Entscheidung verlangt nicht, vorher das ganze Leben neu zu ordnen oder sämtliche Aufgaben perfekt aufzulisten; ein einzelner Punkt kann heute genügen.",ideas:[{id:"executable-next-step",title:"Übersetze die Verpflichtung in eine beobachtbare Handlung",idea:"Allen empfiehlt, vor dem Ausführungszeitpunkt festzulegen, was eine Aufgabe konkret zu tun bedeutet. Ersetze einen breiten Projekttitel durch eine Handlung mit sichtbarem Beginn und sinnvollem Ende, und prüfe, ob sie Informationen, eine andere Person oder noch fehlende Ressourcen erfordert. Als ODA-Anpassung kann eine aufgeschobene Bewerbung bedeuten, das Formular zu öffnen und die erste fehlende Angabe zu identifizieren, statt nur vage Erledigung zu versprechen. Eine klare Handlung kann weiter schwierig sein, zeigt aber zumindest, welcher Schwierigkeit du gegenüberstehst und welche Hilfe nötig sein könnte; unklare Ausführung und fehlende Information sind verschiedene Probleme.",research:"Konkrete Hinweis-Reaktions-Pläne besitzen metaanalytische Unterstützung: Gollwitzer und Sheeran fanden bessere durchschnittliche Zielerreichung in 94 unterschiedlichen Tests. Die Evidenz betrifft eine erkennbare Situation verbunden mit einer gewählten Handlung, nicht Allens Gesamtsystem oder das Verschwinden von Vermeidung durch gute Formulierung allein. Eine konkrete nächste Handlung entspricht dem untersuchten Prinzip eher, wenn du auch eine realistische Gelegenheit nennst. Begrenze das positive Urteil auf die Planung der Ausführung. Eine reine Projektliste oder ein Plan mit unerreichbarer Hilfe erhält dadurch nicht automatisch die gemessenen Vorteile. Ist die Gelegenheit nicht verfügbar, halte das fest und wähle neu, statt geplante Arbeit als tatsächliche Handlung auszugeben.",verdict:"supported",sourceIds:["if-then-plans"]},{id:"unfinished-obligation",title:"Gib der Erinnerung einen glaubwürdigen Plan",idea:"Das Buch schlägt vor, Verpflichtungen in einem externen System aufzubewahren, um sie ohne ständiges Wiederholen derselben Entscheidung wiederzufinden. Unterscheide das Notieren einer Sorge davon, wie du ihren beeinflussbaren Teil angehst, denn viele ungelöste Erinnerungen können weiterhin Aufmerksamkeit fordern. Schreibe die nächste machbare Handlung und den Zeitpunkt ihrer Prüfung auf; wartest du auf jemanden, notiere das Fehlende, statt Beschäftigung zu erfinden. Die Erinnerung soll Information bewahren und der Plan die nächste Wahl auffindbar machen, ohne zu unterstellen, dass sich alle offenen Angelegenheiten heute durch deinen eigenen Einsatz lösen lassen.",research:"Masicampo und Baumeister fanden in kontrollierten Experimenten, dass konkrete Pläne manche Störungen durch unerfüllte Ziele in anderen Laboraufgaben verringerten. Die Teilnehmenden waren überwiegend Studierende, mit Ergebnissen zu Lesen, Wortzugänglichkeit und Anagrammen. Das ist ein vielversprechender Hinweis auf den Unterschied zwischen einem Ziel mit und ohne Plan, kein Beweis für anhaltende innere Ruhe nach dem vollständigen Erfassen aller Verpflichtungen. Die Arbeit prüft weder das gesamte System noch die Zweiminutenhandlung hier; eine unabhängige direkte Bestätigung dieses Verfahrens bleibt unsicher. Probiere für einen wiederkehrenden Punkt einen glaubwürdigen Plan und beurteile den praktischen Verlauf, ohne die Verpflichtung schon als erledigt einzustufen.",verdict:"mixed",sourceIds:["unfinished-goal-plans"]},{id:"current-record",title:"Prüfe, ob die Liste noch deine Realität beschreibt",idea:"Allens Ansatz hängt vom erneuten Prüfen der Verpflichtungen ab, weil alte Pläne nicht mehr zu Arbeit, Zeit und Verantwortung passen können. Nutze die Übersicht, um Erledigtes zu entfernen, eine blockierte Handlung zu erkennen und einem verbleibenden Punkt eine echte Gelegenheit zu geben, statt die Vollständigkeit der Liste zu bewundern. Übersteigt sie deine Kapazität, reduziere oder verhandle Verpflichtungen neu, anstatt sie bloß eleganter anzuordnen. Die Überprüfung soll eine Arbeitsentscheidung ermöglichen; sie kann selbst zur Vermeidung werden, wenn sie ständig den bekannten nächsten Schritt ersetzt, und verdient dann dieselbe ehrliche Prüfung wie jede andere Aktivität.",research:"Harkin und sein Team fanden in 138 randomisierten Studien einen durchschnittlichen Nutzen von Interventionen zur Fortschrittsbeobachtung. Das unterstützt den Vergleich von Plan und tatsächlichem Fortschritt, doch die unterschiedlichen Verfahren bestimmen kein überall optimales Wochenritual. Die Ergebnisse zu Aufschreiben und Berichten verpflichten nicht zur Offenlegung privater Vorhaben und machen das Ordnen einer Liste nicht zur Erfüllung ihrer Aufgaben. Gestützt ist das Prüfen des wirklichen Fortschritts und eine passende Reaktion. Vergleiche Absicht, Versuch und Ergebnis und ändere den Plan bei Abweichungen. Eine abgehaltene Überprüfung ist für sich noch kein Wirksamkeitsbeleg; ihre nützliche Information muss in die nächste Entscheidung einfließen, statt nur weitere Verwaltungsarbeit zu schaffen.",verdict:"supported",sourceIds:["progress-monitoring"]},{id:"support-boundary",title:"Baue ein System auf, das du tatsächlich nutzen kannst",idea:"Allen möchte Verpflichtungen in einem externen System aufbewahren, das aktuell und zugänglich genug für praktische Arbeitsentscheidungen bleibt. Beginne mit einem Ort, den du wirklich prüfst, halte die Verwaltung überschaubar und ändere die Struktur, wenn ihre Pflege mehr Aufwand als nützliche Handlung verlangt. Entscheidend ist, ob du eine konkrete Wahl findest oder eine Verpflichtung zum Neuverhandeln erkennst, nicht ob das Archiv perfekt aussieht. Betreffen anhaltende Schwierigkeiten mehrere Lebensbereiche, ziehe qualifizierte Unterstützung während deiner Alltagsversuche in Betracht; du musst diese Methode nicht abschließen, in einem Kurs scheitern oder Disziplin beweisen, bevor du Abklärung oder Anpassungen ansprechen darfst.",research:"Ein Cochrane-Überblick über 14 randomisierte Studien bei Erwachsenen mit ADHS fand begrenzte Vorteile strukturierter kognitiv-verhaltenstherapeutischer Programme. Die Evidenzsicherheit reichte von sehr niedrig bis moderat, und Ergebnisse hingen von der Vergleichsbedingung ab. Listen und Kalender stehen in einem veröffentlichten klinischen Protokoll, doch dessen Beschreibung bestätigt ihre therapeutische Wirkung nicht einzeln. Keine Quelle macht Getting Things Done zu einer ADHS-Behandlung oder zeigt, dass eine Erinnerung klinische Schwierigkeiten löst. Für die Übertragung auf anhaltende Aufmerksamkeitsprobleme ist der Befund gemischt: Alltagshilfe ist möglich, ODA ist keine Behandlung und Medikamentenentscheidungen gehören zu deinem medizinischen Betreuungsteam. Ein eigener Organisationsversuch muss die Abklärung deshalb nicht hinauszögern.",verdict:"mixed",sourceIds:["adult-adhd-cbt","adhd-skills-protocol"]}],action:{title:"Kläre in zwei Minuten einen festgefahrenen Punkt",steps:["Wähle eine offene Verpflichtung und notiere eine sichtbare nächste Handlung, die heute beginnen könnte.","Schreibe eine machbare Uhrzeit oder einen vertrauten Hinweis und fehlende Informationen dazu.","Lege diesen einen Plan in deinen üblichen Notizen ab und lass Platz für den späteren Versuch."],decision:"Heute notiere ich die nächste Handlung eines offenen Punkts, eine Gelegenheit und fehlende Informationen."},takeaway:"Behalte die konkrete Handlung und die Prüfung an der Realität. Gehe vorsichtig mit dem Versprechen dauerhaft geistiger Klarheit um: Planungsexperimente belegen nicht, dass ein ganzes System Stress entfernt. Die zweiminütige Klärung ist eine ODA-Anpassung, keine geprüfte Behandlungsdosis. Bei übermäßiger Belastung oder anhaltender Beeinträchtigung kann Unterstützung der nützliche nächste Schritt sein. Ein System verdient seinen Platz, wenn es Handeln oder Neuverhandeln erleichtert, statt einen weiteren Maßstab zu schaffen. Frage deshalb, welche konkrete Entscheidung leichter wurde und wo die Grenzen liegen; eine umfassend aussehende Liste beantwortet diese Frage nicht von allein."},it:{hook:"La lista è piena, ma non sai cosa fare adesso. Rendi eseguibile un solo punto.",intro:"Allen si occupa di gestire gli impegni senza doverli ricostruire mentalmente ogni volta che inizi a lavorare. ODA esamina la chiarezza dell’azione successiva, il piano per un obbligo incompleto, la precisione della revisione e i limiti di un sistema personale. Ogni tema richiede un giudizio separato: le prove sulla pianificazione non convalidano ogni caratteristica di un intero metodo di produttività. Parti da un punto che continua a tornarti in mente. Carta o uno strumento gratuito già disponibile possono bastare. Non devi riorganizzare tutta la vita né inventariare perfettamente ogni responsabilità prima di prendere una decisione utile per oggi.",ideas:[{id:"executable-next-step",title:"Trasforma l’impegno in un’azione osservabile",idea:"Allen invita a decidere cosa significhi fare una cosa prima di arrivare al momento dell’esecuzione. Sostituisci il nome generale di un progetto con un’azione dal principio visibile e dalla conclusione ragionevole, verificando se servano informazioni, un’altra persona o una risorsa ancora assente. Come adattamento ODA, una domanda rinviata può diventare aprire il modulo e identificare il primo dato mancante, invece di promettere vagamente di occuparsene. Un’azione chiara può restare difficile, ma almeno distingue quale difficoltà hai davanti e cosa potrebbe aiutarti; non sapere come iniziare è diverso dal sapere quale informazione non possiedi.",research:"I piani specifici segnale-risposta hanno sostegno meta-analitico: Gollwitzer e Sheeran hanno trovato un miglioramento medio nel raggiungimento degli obiettivi in 94 verifiche differenti. La ricerca riguarda una situazione riconoscibile associata a un comportamento scelto, non l’intero sistema di Allen né l’eliminazione dell’evitamento con la sola formulazione. L’azione concreta si avvicina al principio studiato quando definisci anche un’occasione realistica per provarla. Limita il giudizio favorevole alla preparazione dell’esecuzione. Una lista di progetti o un piano dipendente da aiuto indisponibile non ottengono automaticamente i benefici osservati. Se l’occasione non esiste, registralo e scegline un’altra senza contare l’intenzione come lavoro realmente svolto.",verdict:"supported",sourceIds:["if-then-plans"]},{id:"unfinished-obligation",title:"Affianca al promemoria un piano credibile",idea:"Il libro propone di conservare gli impegni in un sistema esterno per ritrovarli senza ripetere continuamente la stessa decisione nella testa. Distingui tra annotare una preoccupazione e decidere come affrontarne la parte su cui puoi agire, perché una raccolta di questioni irrisolte può ancora chiedere attenzione. Scrivi il passo fattibile e quando lo rivedrai; se aspetti una persona, indica cosa manca invece di inventare attività. Il promemoria preserva informazioni e il piano rende rintracciabile la scelta successiva, senza presupporre che ogni obbligo sia subito risolvibile con uno sforzo tuo o che tutti i punti abbiano la stessa priorità.",research:"Masicampo e Baumeister hanno trovato in esperimenti controllati che piani specifici riducevano alcune interferenze di obiettivi incompleti su compiti di laboratorio non collegati. I partecipanti erano soprattutto universitari e gli esiti includevano lettura, accessibilità di parole e anagrammi. È un sostegno promettente alla differenza tra un obiettivo senza piano e uno pianificato, non una prova di calma mentale duratura quando si raccoglie tutto in una lista. L’articolo non testa il sistema intero né l’azione di due minuti qui proposta; la conferma diretta indipendente di questa procedura resta incerta. Prova un piano credibile per un obbligo ricorrente e osserva il risultato pratico, senza registrare l’obbligo stesso come concluso.",verdict:"mixed",sourceIds:["unfinished-goal-plans"]},{id:"current-record",title:"Verifica che la lista descriva ancora la realtà",idea:"L’approccio di Allen dipende dal rivedere gli impegni, perché un vecchio piano può non corrispondere più a lavoro, tempo e responsabilità disponibili. Usa la revisione per rimuovere il completato, riconoscere un passo bloccato e scegliere quale punto meriti una vera occasione, non per ammirare la completezza della lista. Se supera la tua capacità, riduci o rinegozia gli impegni invece di ordinarli meglio. La revisione deve sostenere una decisione sul lavoro; può diventare evitamento se prende ripetutamente il posto dell’azione che sai già iniziare, e va valutata con la stessa sincerità delle altre attività.",research:"Harkin e colleghi hanno trovato un beneficio medio degli interventi di monitoraggio in 138 studi randomizzati. Ciò sostiene il confronto tra piano e progresso osservato, ma formati differenti non identificano un rituale settimanale ottimale per tutti. Le analisi su registrazione e comunicazione non obbligano a condividere impegni privati né rendono il riordino della lista equivalente a completarli. Il principio sostenuto è esaminare il progresso reale e rispondervi. Confronta intenzione, tentativo e risultato e modifica il piano dove divergono. L’esistenza di una revisione non basta a dimostrare efficacia: cerca quale informazione modifica la scelta successiva, mantenendo eventuale condivisione sicura e facoltativa, invece di aggiungere soltanto altro lavoro amministrativo.",verdict:"supported",sourceIds:["progress-monitoring"]},{id:"support-boundary",title:"Costruisci un sistema che riesci davvero a usare",idea:"Allen vuole che gli impegni siano conservati in un sistema esterno abbastanza aggiornato e accessibile da sostenere le scelte di lavoro. Parti da un luogo che consulterai davvero, limita l’amministrazione e modifica la struttura quando richiede più manutenzione che azione utile. Non devi ottenere un archivio perfetto perché il sistema abbia valore: cerca se ti aiuta a trovare una decisione concreta o a riconoscere un impegno da rinegoziare. Se difficoltà persistenti coinvolgono più aree della vita, considera un professionista qualificato mentre provi gli aiuti quotidiani; completare questo metodo non è un requisito per chiedere valutazione o sostegno.",research:"Una revisione Cochrane di 14 studi randomizzati sul DDAI negli adulti ha trovato benefici qualificati di programmi strutturati di terapia cognitivo-comportamentale. La certezza variava da molto bassa a moderata e gli esiti dipendevano dal confronto. Liste e calendari compaiono in un protocollo clinico pubblicato, ma la loro efficacia terapeutica non è convalidata separatamente in quella descrizione. Nessuna fonte stabilisce che Getting Things Done sia una cura per il DDAI o che un promemoria risolva una difficoltà clinica. Il giudizio è misto per estendere il sistema a problemi di attenzione persistenti: può aiutare nel quotidiano, mentre ODA non è un trattamento e le decisioni sui farmaci spettano al percorso clinico. Una prova di organizzazione non deve rimandare una valutazione necessaria.",verdict:"mixed",sourceIds:["adult-adhd-cbt","adhd-skills-protocol"]}],action:{title:"Chiarisci un punto bloccato in due minuti",steps:["Scegli un impegno incompleto e scrivi l’azione visibile successiva che potresti iniziare oggi.","Indica un orario o segnale abituale per provarla e le informazioni mancanti.","Metti questo singolo piano nelle tue note abituali e lascia spazio per registrare il tentativo."],decision:"Oggi scriverò il passo successivo di un impegno, l’occasione per provarlo e le informazioni mancanti."},takeaway:"Conserva l’azione concreta e la revisione che verifica la realtà. Usa cautela con la promessa di una mente sempre libera: esperimenti di pianificazione non dimostrano che un sistema intero elimini lo stress. Il chiarimento di due minuti è un adattamento ODA, non una dose di trattamento studiata. Se la barriera è un carico eccessivo o una difficoltà persistente, chiedere sostegno può essere il passo utile. Un sistema merita posto quando aiuta ad agire o rinegoziare, senza diventare un altro standard da soddisfare; controlla quale scelta concreta facilita e dove invece non basta."}}};export{e as default};
